export function initAuthHandlers() {
  // ── Password show/hide toggle ─────────────────────────────────────────────
  window.PathoApp._togglePwd = (inputId, btn) => {
    const input = document.getElementById(inputId);
    if (!input) return;
    const isHidden = input.type === 'password';
    input.type = isHidden ? 'text' : 'password';
    const icon = btn.querySelector('i');
    if (icon) icon.className = isHidden ? 'fas fa-eye-slash' : 'fas fa-eye';
  };

  // ── Password strength indicator ───────────────────────────────────────────
  window.PathoApp._updatePwdStrength = (password, barId) => {
    const bar = document.getElementById(barId);
    if (!bar) return;
    let score = 0;
    if (password.length >= 8) score++;
    if (password.length >= 12) score++;
    if (/[A-Z]/.test(password)) score++;
    if (/[0-9]/.test(password)) score++;
    if (/[^A-Za-z0-9]/.test(password)) score++;
    const colors = ['#ef4444', '#f97316', '#eab308', '#22c55e', '#16a34a'];
    const widths = ['20%', '40%', '60%', '80%', '100%'];
    bar.style.background = score > 0 ? colors[score - 1] : '#374151';
    bar.style.width = score > 0 ? widths[score - 1] : '0';
  };

  // ── Login ────────────────────────────────────────────────────────────
  window.PathoApp.handleLogin = async () => {
    const emailEl = document.getElementById('login-email');
    const passEl = document.getElementById('login-password');
    const errorEl = document.getElementById('login-error');
    const btnText = document.getElementById('login-btn-text');
    const btn = document.getElementById('btn-login');
    
    const email = emailEl ? emailEl.value.trim() : '';
    const pass = passEl ? passEl.value : '';

    if (!email || !pass) {
      if (errorEl) { errorEl.textContent = 'Please fill in both fields.'; errorEl.classList.add('show'); }
      return;
    }

    if (errorEl) errorEl.classList.remove('show');
    if (btn) btn.disabled = true;
    if (btnText) btnText.textContent = 'Signing in…';

    try {
      const res = await ApiService.login(email, pass);
      const userObj = res.user || res;
      localStorage.setItem('pathoai_logged_in', 'true');
      setState({ currentUser: userObj });
      
      // Fetch fresh patient records from backend
      try {
        const patients = await ApiService.getPatients();
        setState({ patients });
      } catch (pErr) {
        console.warn('Patient fetch warning:', pErr);
      }

      showToast('Welcome back, ' + (userObj.full_name || email), 'success');
      setView('view-app');
    } catch (err) {
      if (errorEl) { errorEl.textContent = err.message || 'Login failed. Check your credentials.'; errorEl.classList.add('show'); }
    } finally {
      if (btn) btn.disabled = false;
      if (btnText) btnText.textContent = 'Sign In';
    }
  };

  // ── Register ─────────────────────────────────────────────────────────
  window.PathoApp.handleRegister = async () => {
    const name = document.getElementById('reg-name').value.trim();
    const lic = document.getElementById('reg-license').value.trim();
    const inst = document.getElementById('reg-institution').value.trim();
    const email = document.getElementById('reg-email').value.trim();
    const pass = document.getElementById('reg-password').value;
    const confirmPass = document.getElementById('reg-confirm-password') ? document.getElementById('reg-confirm-password').value : pass;
    const errorEl = document.getElementById('reg-error');
    const btn = document.getElementById('btn-register');
    const btnText = document.getElementById('reg-btn-text');

    if (!name || !email || !pass) {
      if (errorEl) { errorEl.textContent = 'Name, email, and password are required.'; errorEl.classList.add('show'); }
      return;
    }
    if (name.length < 2) {
      if (errorEl) { errorEl.textContent = 'Full name must be at least 2 characters.'; errorEl.classList.add('show'); }
      return;
    }
    if (pass.length < 8) {
      if (errorEl) { errorEl.textContent = 'Password must be at least 8 characters long.'; errorEl.classList.add('show'); }
      return;
    }
    if (pass !== confirmPass) {
      if (errorEl) { errorEl.textContent = 'Passwords do not match.'; errorEl.classList.add('show'); }
      return;
    }

    if (errorEl) errorEl.classList.remove('show');
    if (btn) btn.disabled = true;
    if (btnText) btnText.textContent = 'Registering…';

    try {
      await ApiService.register({ email, password: pass, full_name: name, license_id: lic, institution: inst });
      showToast('Account registered successfully! Please sign in.', 'success');
      // Auto-fill email in login form so user doesn't have to retype
      const loginEmailEl = document.getElementById('login-email');
      if (loginEmailEl) loginEmailEl.value = email;
      setView('view-login');
    } catch (err) {
      if (errorEl) { errorEl.textContent = err.message || 'Registration failed'; errorEl.classList.add('show'); }
    } finally {
      if (btn) btn.disabled = false;
      if (btnText) btnText.textContent = 'Register Credentials';
    }
  };


  // ── Forgot Password Step 1: Send OTP ─────────────────────────────────
  window.PathoApp.handleSendOTP = async () => {
    const emailEl = document.getElementById('forgot-email');
    const errorEl = document.getElementById('forgot-error');
    const successEl = document.getElementById('forgot-success');
    const btn = document.getElementById('btn-send-otp');
    const btnText = document.getElementById('send-otp-btn-text');

    const email = emailEl ? emailEl.value.trim() : '';
    if (!email) {
      if (errorEl) { errorEl.textContent = 'Please enter your registered email.'; errorEl.classList.add('show'); }
      return;
    }

    if (errorEl) errorEl.classList.remove('show');
    if (successEl) successEl.style.display = 'none';
    if (btn) btn.disabled = true;
    if (btnText) btnText.textContent = 'Sending OTP…';

    try {
      const res = await ApiService.forgotPassword(email);

      // Store the email for step 2 verification & resend
      window.PathoApp._otpEmail = email;

      // Move to step 2
      const step1 = document.getElementById('forgot-step1');
      const step2 = document.getElementById('forgot-step2');
      const emailDisplay = document.getElementById('otp-email-display');

      if (step1) step1.style.display = 'none';
      if (step2) step2.style.display = 'block';
      if (emailDisplay) emailDisplay.textContent = email;

      showToast(res.msg || 'OTP sent! Please check your email for the 6-digit code.', 'success');
    } catch (err) {
      if (errorEl) { errorEl.textContent = err.message || 'Failed to send OTP. Please try again.'; errorEl.classList.add('show'); }
    } finally {
      if (btn) btn.disabled = false;
      if (btnText) btnText.textContent = 'Send OTP Code';
    }
  };

  // ── Resend OTP Handler ───────────────────────────────────────────────
  window.PathoApp.handleResendOTP = async () => {
    const email = window.PathoApp._otpEmail || (document.getElementById('forgot-email') ? document.getElementById('forgot-email').value.trim() : '');
    const errorEl = document.getElementById('otp-verify-error');
    const successEl = document.getElementById('otp-verify-success');

    if (errorEl) errorEl.classList.remove('show');
    if (successEl) successEl.style.display = 'none';

    if (!email) {
      if (errorEl) { errorEl.textContent = 'Email address missing. Please go back and enter your email.'; errorEl.classList.add('show'); }
      return;
    }

    try {
      const res = await ApiService.forgotPassword(email);
      showToast('A new 6-digit OTP code has been sent to your email.', 'info');
      if (successEl) {
        successEl.textContent = 'New OTP code sent to your email address.';
        successEl.style.display = 'block';
      }
    } catch (err) {
      if (errorEl) { errorEl.textContent = err.message || 'Failed to resend OTP.'; errorEl.classList.add('show'); }
    }
  };

  // ── Forgot Password Step 2: Verify OTP + Reset Password ──────────────
  window.PathoApp.handleVerifyOTPReset = async () => {
    const otpInput = document.getElementById('otp-code-input');
    const newPassInput = document.getElementById('new-password-input');
    const confirmPassInput = document.getElementById('confirm-password-input');
    const errorEl = document.getElementById('otp-verify-error');
    const successEl = document.getElementById('otp-verify-success');
    const btn = document.getElementById('btn-verify-otp');
    const btnText = document.getElementById('verify-otp-btn-text');

    const otp = otpInput ? otpInput.value.trim() : '';
    const newPass = newPassInput ? newPassInput.value : '';
    const confirmPass = confirmPassInput ? confirmPassInput.value : '';
    const email = window.PathoApp._otpEmail || '';

    if (errorEl) errorEl.classList.remove('show');
    if (successEl) successEl.style.display = 'none';

    if (!otp || !/^\d{6}$/.test(otp)) {
      if (errorEl) { errorEl.textContent = 'Please enter the 6-digit numeric OTP code.'; errorEl.classList.add('show'); }
      return;
    }
    if (!newPass || newPass.length < 6) {
      if (errorEl) { errorEl.textContent = 'Password must be at least 6 characters.'; errorEl.classList.add('show'); }
      return;
    }
    if (newPass !== confirmPass) {
      if (errorEl) { errorEl.textContent = 'Passwords do not match.'; errorEl.classList.add('show'); }
      return;
    }
    if (!email) {
      if (errorEl) { errorEl.textContent = 'Session expired. Please go back and request a new OTP.'; errorEl.classList.add('show'); }
      return;
    }

    if (btn) btn.disabled = true;
    if (btnText) btnText.textContent = 'Resetting…';

    try {
      const res = await ApiService.verifyOTPReset(email, otp, newPass);
      showToast('Password reset successful! Please sign in with your new password.', 'success');

      if (successEl) {
        successEl.textContent = res.msg || 'Password reset successful! Redirecting to Sign In...';
        successEl.style.display = 'block';
      }

      // Clear session state and navigate back to login
      window.PathoApp._otpEmail = null;
      setTimeout(() => {
        if (otpInput) otpInput.value = '';
        if (newPassInput) newPassInput.value = '';
        if (confirmPassInput) confirmPassInput.value = '';
        window.PathoApp._resetForgotStep1();
        setView('view-login');
      }, 1500);
    } catch (err) {
      if (errorEl) { errorEl.textContent = err.message || 'Invalid or expired OTP code.'; errorEl.classList.add('show'); }
    } finally {
      if (btn) btn.disabled = false;
      if (btnText) btnText.textContent = 'Reset Password';
    }
  };

  // ── Helper: go back to Step 1 from Step 2 ─────────────────────────────
  window.PathoApp._resetForgotStep1 = () => {
    const step1 = document.getElementById('forgot-step1');
    const step2 = document.getElementById('forgot-step2');
    const errorEl = document.getElementById('forgot-error');
    const verifyError = document.getElementById('otp-verify-error');

    if (step1) step1.style.display = 'block';
    if (step2) step2.style.display = 'none';
    if (errorEl) errorEl.classList.remove('show');
    if (verifyError) verifyError.classList.remove('show');
    window.PathoApp._otpEmail = null;
  };

  // ── Logout ─────────────────────────────────────────────────────────────
  window.PathoApp.handleLogout = async () => {
    localStorage.removeItem('pathoai_logged_in');
    try {
      await ApiService.logout();
    } catch (err) {
      console.warn('Logout API error:', err);
    } finally {
      setState({ currentUser: null });
      showToast('Logged out of PathoAI', 'info');
      setView('view-login');
    }
  };

}
